/** Return fresh job records in input order, dropping invalid jobs. */
export function normalizeJobs(jobs) {
  const normalized = [];

  for (const job of jobs) {
    if (job == null) continue;
    const { id, duration } = job;
    if (typeof id !== 'string' || id.length === 0) continue;
    if (!Number.isInteger(duration) || duration <= 0) continue;
    normalized.push({ id, duration });
  }

  return normalized;
}

/** Return fresh job records in input order, dropping invalid jobs. */
export function normalizeJobs(jobs) {
  const normalized = [];

  for (const job of jobs) {
    if (job == null) continue;
    const { id, duration } = job;
    if (typeof id !== 'string' || id.length === 0) continue;
    if (!Number.isInteger(duration) || duration <= 0) continue;
    normalized.push({ id, duration });
  }

  return normalized;
}

/** Schedule normalized jobs in input order using two slots. */
export function scheduleJobs(jobs) {
  const available = [0, 0];
  const scheduled = [];

  for (const { id, duration } of jobs) {
    const slot = available[0] <= available[1] ? 0 : 1;
    const start = available[slot];
    const end = start + duration;
    scheduled.push({ id, start, end, slot });
    available[slot] = end;
  }

  return scheduled;
}

export function normalizeJobs(jobs) {
  const normalized = [];

  for (const job of jobs) {
    if (
      job != null &&
      typeof job.id === 'string' &&
      job.id.length > 0 &&
      Number.isInteger(job.duration) &&
      job.duration > 0
    ) {
      normalized.push({ id: job.id, duration: job.duration });
    }
  }

  return normalized;
}

