      job.duration > 0
    ) {
      normalized.push({ id: job.id, duration: job.duration });
    }
  }

  return normalized;
}

export function scheduleJobs(jobs) {
  const availability = [0, 0];

  return normalizeJobs(jobs).map(({ id, duration }) => {
    const slot = availability[0] <= availability[1] ? 0 : 1;
    const start = availability[slot];
    const end = start + duration;
    availability[slot] = end;

    return { id, start, end, slot };
  });
}

